import json
d=json.load(open('data/b760_discharge.json',encoding='utf-8'))
def show(k,v,ind=''):
    if isinstance(v,dict):
        print(ind+str(k)+':')
        for a,b in v.items(): show(a,b,ind+'  ')
    elif isinstance(v,list):
        print(ind+str(k)+': list',len(v))
        for i,b in enumerate(v[:6]): show(i,b,ind+'  ')
    else:
        print(ind+str(k)+': '+str(v)[:700])
for k,v in d.items(): show(k,v)
"

